<script setup lang="ts">
const props=defineProps<{days:number,end?:string,start?:string}>()
const stroke=ref('freestyle'),distance=ref(100),pool=ref(25)
const query=computed(()=>({days:props.days||3650,start:props.start,end:props.end||undefined,stroke:stroke.value,distance:distance.value,pool:pool.value}))
const {data:c,error}=await useFetch<any>('/api/platform/compare',{query})
const selected=ref<any>(null)
const charts=computed(()=>[...new Set((c.value?.sessions||[]).map((s:any)=>s.watch))].map(w=>({watch:w,rows:c.value.sessions.filter((s:any)=>s.watch===w)})))
const fmt=(v:any,n=1)=>v==null?'—':Number(v).toLocaleString('it-IT',{maximumFractionDigits:n})
const pace=(v:any)=>{if(v==null)return '—';const s=Math.round(v);return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
watch(query,()=>{selected.value=null})
</script>
<template><section class="space-y-5"><div class="panel"><p class="eyebrow">CONFRONTO DEL NUOTO · CONTESTO OMOGENEO</p><h2 class="text-xl font-semibold mt-2">Le ripetute, seduta per seduta.</h2><p class="muted mt-2">Seleziona distanza, stile e vasca. La sintesi usa una mediana per seduta, così un allenamento con più lap non pesa più degli altri.</p><div class="flex flex-wrap gap-3 mt-5"><select v-model="stroke" aria-label="Stile confronto"><option value="freestyle">Stile libero</option><option value="backstroke">Dorso</option><option value="breaststroke">Rana</option><option value="butterfly">Farfalla</option><option value="mixed">Misto</option><option value="drill">Tecnica</option></select><select v-model.number="distance" aria-label="Distanza ripetuta"><option v-for="d in [25,50,100,200,300,400,500,800,1000,1500]" :value="d">{{d}} m</option></select><select v-model.number="pool" aria-label="Vasca confronto"><option :value="25">Vasca 25 m</option><option :value="50">Vasca 50 m</option></select></div><p v-if="error" class="text-amber-300 mt-3">Confronto non disponibile. Controlla i filtri o riprova.</p><p v-if="c" class="muted mt-3">{{c.session_n}} sedute · {{c.lap_n}} lap registrati · {{c.start}} → {{c.end}}</p></div>
<template v-if="c"><div class="panel"><h3 class="font-semibold mb-4">Passo attivo delle ripetute · secondi/100 m</h3><div v-for="chart in charts" class="mt-4"><p class="muted mb-2">Orologio: {{chart.watch}}</p><TrendChart :rows="chart.rows" x="date" :series="[{key:'median_pace',label:'Mediana della seduta'},{key:'min_pace',label:'Lap più rapido',color:'#60a5fa'},{key:'max_pace',label:'Lap più lento',color:'#a78bfa'}]" @select="selected=$event"/></div><p v-if="!charts.length" class="muted">Nessun lap corrispondente nel periodo.</p><p class="muted mt-3">I punti descrivono i lap corrispondenti al filtro. Un lap registrato non certifica una serie prescritta. Seleziona un punto per leggere tutte le prove.</p></div><div class="panel table-wrap"><h3 class="font-semibold mb-3">Prima e seconda metà del periodo</h3><p class="muted mb-4">Separazione al {{c.midpoint}}. Modelli di orologio diversi restano gruppi distinti.</p><table><thead><tr><th>Orologio</th><th>Sedute prima / dopo</th><th>Mediana prima</th><th>Mediana dopo</th><th>Δ secondi/100 m</th></tr></thead><tbody><tr v-for="g in c.comparisons"><td>{{g.watch}}</td><td>{{g.before_n}} / {{g.after_n}}</td><td>{{pace(g.before_pace)}}</td><td>{{pace(g.after_pace)}}</td><td>{{g.delta_s==null?'Dati insufficienti':fmt(g.delta_s)}}</td></tr></tbody></table><p v-if="!c.comparisons.length" class="muted mt-4">Nessuna ripetuta corrispondente: cambia il filtro o amplia il periodo.</p><p class="muted mt-4" v-for="s in c.limits">{{s}}</p></div><div class="panel table-wrap"><h3 class="font-semibold mb-3">Sedute che sostengono il confronto</h3><table><thead><tr><th>Seduta</th><th>Orologio</th><th>Lap</th><th>Passo mediano</th><th>Dispersione · s/100 m</th><th>SWOLF · n</th><th>Ultimo vs primo</th><th>Contesto dichiarato</th></tr></thead><tbody><tr v-for="s in c.sessions"><td><button class="text-green-400" @click="selected=s">{{s.date}} · {{s.name}}</button></td><td>{{s.watch}}</td><td>{{s.laps_n}}</td><td>{{pace(s.median_pace)}}</td><td>{{fmt(s.pace_sd)}}</td><td>{{fmt(s.swolf)}} · {{s.swolf_n}}</td><td>{{fmt(s.drift_pct)}}%</td><td>{{s.annotation?.intent||'Non dichiarato'}}</td></tr></tbody></table></div><div v-if="selected" class="panel table-wrap"><div class="flex gap-3 items-center justify-between"><h3 class="font-semibold">Ripetute del {{selected.date}}</h3><NuxtLink :to="'/activity/'+selected.activity_id" class="text-green-400 text-sm">Apri la scheda FIT →</NuxtLink></div><table class="mt-4"><thead><tr><th>Lap registrato</th><th>Distanza</th><th>Tempo · s</th><th>Passo /100 m</th><th>SWOLF</th><th>Bracciate</th></tr></thead><tbody><tr v-for="l in selected.laps"><td>{{l.lap_index}}</td><td>{{l.distance_m}} m</td><td>{{fmt(l.duration_s)}}</td><td>{{pace(l.pace_per_100m_s)}}</td><td>{{fmt(l.swolf)}}</td><td>{{l.total_strokes??'—'}}</td></tr></tbody></table></div></template></section></template>
